//! The host services a detector may call.

use std::path::Path;

use crate::error::HostError;
use crate::types::{ExecRequest, ExecResult, FileInfo, HttpRequest, HttpResponse, LogLevel};

/// Host services available to a detector, each gated by a manifest capability.
///
/// This is the native, mockable façade of the WIT `host` interface. Detector
/// logic takes `&mut dyn Host`, so unit tests pass a [`MockHost`](crate::MockHost)
/// while the wasm shell generated by [`bind_detector!`](crate::bind_detector)
/// passes a host implementation that forwards to the imported functions.
///
/// Filesystem *content* is **not** part of this trait: in v1 the host grants a
/// read-only WASI preopen of `/`, so plugins read files with `std::fs`. This
/// trait only covers what WASI lacks (`stat` metadata, process spawning,
/// persistent cache, HTTP and logging).
pub trait Host {
    /// Unix metadata (mode/uid/gid/nlink) for `path`, filling the gap WASI 0.2
    /// leaves. Metadata only; no content is read.
    fn stat(&mut self, path: &Path) -> Result<FileInfo, HostError>;

    /// Run an allowlisted program. The host enforces the program allowlist,
    /// timeout and output caps.
    fn exec(&mut self, request: &ExecRequest) -> Result<ExecResult, HostError>;

    /// Read a persistent per-plugin cache entry.
    fn cache_get(&mut self, key: &str) -> Option<Vec<u8>>;

    /// Write a persistent per-plugin cache entry.
    fn cache_set(&mut self, key: &str, value: &[u8]) -> Result<(), HostError>;

    /// Perform an allowlisted HTTP request.
    fn http(&mut self, request: &HttpRequest) -> Result<HttpResponse, HostError>;

    /// Emit a diagnostic message. Logging never fails and is not rate-limited
    /// by the contract; keep it to a handful of lines per scan.
    fn log(&mut self, level: LogLevel, message: &str);
}
